    foodUpkeepMult: 1.0,   // the dead eat carrion at the same rate
    farmYield: 'food',   // what this faction's food building actually banks
    words: { food:'carrion', worker:'ghoul', workers:'ghouls' },
    campName: 'Human Outpost',
